#!/usr/bin/env bash
# Builds the translator as WebAssembly for the playground: `site/public/ariadne.{js,wasm}`.
#
# Needs Lean (the pinned toolchain), Node or Bun, git, CMake, and Emscripten's `emcc` on PATH.
# Lean ships no WebAssembly build, so everything the translator runs is compiled here from C:
#   1. Lean's runtime, from the Lean sources at the toolchain's tag, single-threaded (a static page
#      cannot get the cross-origin isolation that WebAssembly threads need);
#   2. the C of the standard library modules the translator imports, generated by the toolchain's own
#      `lean` from the sources it ships (a stage-2 build of just those modules);
#   3. the C of Ariadne's front end and `Web.lean`, generated by Lake.
# Lean's code generator emits portable C (sizes as `sizeof` expressions, small literals below 2^31),
# so the 64-bit host's output compiles for wasm32.
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
playground=$(dirname "$here")
work=${ARIADNE_WASM_WORK:-$playground/.build}
out=$playground/site/public
mkdir -p "$work" "$out"
js=$(command -v bun || command -v node)

prefix=$(lean --print-prefix)
version=$(lean --version | sed -E 's/.*version ([0-9.]+).*/\1/')
jobs=$(nproc 2>/dev/null || echo 4)

# 1. The runtime.
lean4=$work/lean4-v$version
if [ ! -d "$lean4" ]; then
  git clone --quiet --depth 1 --branch "v$version" https://github.com/leanprover/lean4 "$lean4"
  # Without threads, and a stub whose signature drifted from its header in the emscripten branch.
  sed -i 's/set(EMSCRIPTEN_SETTINGS "-s ALLOW_MEMORY_GROWTH=1 -fwasm-exceptions -pthread -flto")/set(EMSCRIPTEN_SETTINGS "-fwasm-exceptions -flto")/; s/string(APPEND LEANC_EXTRA_CC_FLAGS " -pthread")//' \
    "$lean4/src/CMakeLists.txt"
  sed -i 's/^extern "C" LEAN_EXPORT lean_obj_res lean_uv_os_get_group() {/extern "C" LEAN_EXPORT lean_obj_res lean_uv_os_get_group(uint64_t gid) {/' \
    "$lean4/src/runtime/uv/system.cpp"
fi
runtime=$work/runtime
if [ ! -f "$runtime/lib/lean/libleanrt.a" ]; then
  emcmake cmake -S "$lean4/src" -B "$runtime" -DSTAGE=1 -DMULTI_THREAD=OFF -DUSE_GMP=OFF -DUSE_MIMALLOC=OFF \
    -DCMAKE_BUILD_TYPE=Release >/dev/null
  emmake make -C "$runtime" -j"$jobs" leanrt >/dev/null
fi

# 3 (first, as it decides which stdlib modules are needed). Ariadne's front end and the entry points.
(cd "$playground" && lake build Web)
closure=$(LEAN_SRC_PATH="$playground:$playground/..:$prefix/src/lean" "$js" "$here/closure.mjs" Web)

# 2. The standard library modules in the closure.
stdlib=$work/stdlib
mkdir -p "$stdlib"
cat > "$stdlib/lakefile.toml" <<EOF
name = "stdlib"
bootstrap = true
srcDir = "$prefix/src/lean"
leanOptions.linter.coreInternal = true

[[lean_lib]]
name = "Init"

[[lean_lib]]
name = "Std"

[[lean_lib]]
name = "Lean"
EOF
cp "$playground/lean-toolchain" "$stdlib/"
targets=$(echo "$closure" | grep -E '^(Init|Std|Lean)(\.|$)' | sed 's/^/+/; s/$/:c/')
(cd "$stdlib" && lake build $targets >/dev/null)

# Compile and link.
objects=$work/obj
cflags="-O3 -DNDEBUG -fwasm-exceptions -I$runtime/include -w"
compile() { # SOURCE OBJECT
  if [ ! "$2" -nt "$1" ]; then mkdir -p "$(dirname "$2")" && emcc $cflags -c "$1" -o "$2"; fi
}
export -f compile
export cflags
for m in $closure; do
  path=$(echo "$m" | tr . /).c
  for dir in "$stdlib/.lake/build/ir" "$playground/../.lake/build/ir" "$playground/.lake/build/ir"; do
    if [ -f "$dir/$path" ]; then echo "$dir/$path $objects/${path%.c}.o"; break; fi
  done
done | xargs -P "$jobs" -n 2 bash -c 'compile "$0" "$1"'
compile "$here/glue.c" "$objects/glue.o"

[ "$(find "$objects" -name '*.o' | wc -l)" -eq "$(( $(echo "$closure" | wc -l) + 1 ))" ] ||
  { echo "missing object files" >&2; exit 1; }

rm -f "$out/ariadne.js" "$out/ariadne.wasm"
em++ -O3 -fwasm-exceptions $(find "$objects" -name '*.o' | sort) \
  "$runtime/lib/lean/libleanrt.a" "$runtime/libuv/src/libuv/libuv.a" \
  -sMODULARIZE=1 -sEXPORT_ES6=1 -sENVIRONMENT=worker,node -sALLOW_MEMORY_GROWTH=1 -sSTACK_SIZE=16MB \
  -sEXPORTED_FUNCTIONS=_ariadne_init,_ariadne_translate,_ariadne_run,_free \
  -sEXPORTED_RUNTIME_METHODS=UTF8ToString,stringToNewUTF8 \
  -o "$out/ariadne.js" 2>&1 | grep -v 'signature mismatch\|>>> defined as' || true
test -f "$out/ariadne.wasm"
echo "built $(du -h "$out/ariadne.wasm" | cut -f1) $out/ariadne.wasm"
